// RFC 3492 (Punycode) codec, implemented from scratch.
// Parameters for IDNA: base=36, tmin=1, tmax=26, skew=38, damp=700,
// initial_bias=72, initial_n=128.
//
// Semantics match Python's `codecs` punycode codec:
//  - encoding copies basic code points (0x00-0x7F) literally (no case flags),
//  - decoding accepts uppercase ASCII letters as digits (case-insensitive).

const BASE = 36;
const TMIN = 1;
const TMAX = 26;
const SKEW = 38;
const DAMP = 700;
const INITIAL_BIAS = 72;
const INITIAL_N = 128;
const DELIMITER = 0x2d; // '-'

// Maximum 32-bit unsigned accumulator guard (mirrors RFC 3492's int overflow).
const MAXINT = 0x7fffffff;

function basic(cp) {
  return cp < 0x80;
}

// digit -> basic code point (RFC 3492 section 5, encode_digit with lowercase).
function encodeDigit(d) {
  // 0..25 -> 'a'..'z', 26..35 -> '0'..'9'
  return d + 22 + 75 * (d < 26 ? 1 : 0);
}

// basic code point -> digit value, case-insensitive for letters.
function decodeDigit(cp) {
  if (cp >= 0x30 && cp <= 0x39) return cp - 0x30 + 26; // '0'-'9'
  if (cp >= 0x41 && cp <= 0x5a) return cp - 0x41; // 'A'-'Z'
  if (cp >= 0x61 && cp <= 0x7a) return cp - 0x61; // 'a'-'z'
  return BASE; // invalid
}

// Bias adaptation function (RFC 3492 section 6.1).
function adapt(delta, numPoints, firstTime) {
  delta = firstTime ? Math.floor(delta / DAMP) : delta >> 1;
  delta += Math.floor(delta / numPoints);
  let k = 0;
  while (delta > Math.floor(((BASE - TMIN) * TMAX) / 2)) {
    delta = Math.floor(delta / (BASE - TMIN));
    k += BASE;
  }
  return k + Math.floor(((BASE - TMIN + 1) * delta) / (delta + SKEW));
}

function toCodePoints(str) {
  return Array.from(str, (ch) => ch.codePointAt(0));
}

function fromCodePoints(cps) {
  return String.fromCodePoint(...cps);
}

// Encode a string of unicode code points (one DNS label, no "xn--" prefix)
// to its punycode representation.
export function punycodeEncode(input) {
  const cps = toCodePoints(input);
  const output = [];

  let n = INITIAL_N;
  let delta = 0;
  let bias = INITIAL_BIAS;

  // Copy basic code points literally.
  let b = 0;
  for (const cp of cps) {
    if (basic(cp)) {
      output.push(cp);
      b++;
    }
  }

  const h = b;
  if (b > 0) output.push(DELIMITER);

  // Main encoding loop (RFC 3492 section 6.3).
  const inputLength = cps.length;
  while (h < inputLength) {
    // m = smallest code point >= n among the non-basic ones not yet handled.
    let m = MAXINT;
    for (const cp of cps) {
      if (cp >= n && cp < m) m = cp;
    }

    if (m - n > Math.floor((MAXINT - delta) / (h + 1))) {
      throw new Error('punycode encode: overflow');
    }
    delta += (m - n) * (h + 1);
    n = m;

    for (const cp of cps) {
      if (cp < n) {
        if (++delta > MAXINT) throw new Error('punycode encode: overflow');
      } else if (cp === n) {
        let q = delta;
        for (let k = BASE; ; k += BASE) {
          const t = k <= bias ? TMIN : k >= bias + TMAX ? TMAX : k - bias;
          if (q < t) break;
          output.push(encodeDigit(t + ((q - t) % (BASE - t))));
          q = Math.floor((q - t) / (BASE - t));
        }
        output.push(encodeDigit(q));
        bias = adapt(delta, h + 1, h === b);
        delta = 0;
        h++;
      }
    }
    delta++;
    n++;
  }

  return fromCodePoints(output);
}

// Decode a punycode string (ASCII) to the unicode label it represents.
// Throws Error on malformed input (bad digits, overflow, etc.).
export function punycodeDecode(input) {
  const cps = toCodePoints(input);

  // All input must be ASCII.
  for (const cp of cps) {
    if (!basic(cp)) throw new Error('punycode decode: non-ASCII input');
  }

  // Find the last delimiter; basic code points before it are copied as-is.
  let b = 0;
  for (let j = 0; j < cps.length; j++) {
    if (cps[j] === DELIMITER) b = j;
  }

  const output = [];
  for (let j = 0; j < b; j++) {
    output.push(cps[j]);
  }

  let n = INITIAL_N;
  let i = 0;
  let bias = INITIAL_BIAS;

  let idx = b > 0 ? b + 1 : 0;

  while (idx < cps.length) {
    const oldi = i;
    let w = 1;

    for (let k = BASE; ; k += BASE) {
      if (idx >= cps.length) {
        throw new Error('punycode decode: unexpected end of input');
      }
      const digit = decodeDigit(cps[idx++]);
      if (digit >= BASE) {
        throw new Error('punycode decode: invalid digit character');
      }
      if (digit > Math.floor((MAXINT - i) / w)) {
        throw new Error('punycode decode: overflow');
      }
      i += digit * w;
      const t = k <= bias ? TMIN : k >= bias + TMAX ? TMAX : k - bias;
      if (digit < t) break;
      if (w > Math.floor(MAXINT / (BASE - t))) {
        throw new Error('punycode decode: overflow');
      }
      w *= BASE - t;
    }

    const out = output.length + 1;
    bias = adapt(i - oldi, out, oldi === 0);

    if (Math.floor(i / out) > MAXINT - n) {
      throw new Error('punycode decode: overflow');
    }
    n += Math.floor(i / out);
    i %= out;

    output.splice(i, 0, n);
    i++;
  }

  return fromCodePoints(output);
}

// Self-test for /output/lib/punycode.mjs
// Usage: node /output/tools/test-punycode.mjs
import { execFileSync } from 'node:child_process';
import { punycodeEncode, punycodeDecode } from '../lib/punycode.mjs';

let passed = 0;
let failed = 0;
const failures = [];

function check(name, cond, detail = '') {
  if (cond) {
    passed++;
  } else {
    failed++;
    failures.push(`${name}${detail ? ': ' + detail : ''}`);
    console.error(`FAIL ${name}${detail ? ': ' + detail : ''}`);
  }
}

function expectEncode(label, expected) {
  let got;
  try {
    got = punycodeEncode(label);
  } catch (e) {
    check(`encode ${JSON.stringify(label)}`, false, `threw ${e.message}`);
    return;
  }
  check(`encode ${JSON.stringify(label)}`, got === expected, `got ${JSON.stringify(got)}, want ${JSON.stringify(expected)}`);
}

function expectDecode(ascii, expected) {
  let got;
  try {
    got = punycodeDecode(ascii);
  } catch (e) {
    check(`decode ${JSON.stringify(ascii)}`, false, `threw ${e.message}`);
    return;
  }
  check(`decode ${JSON.stringify(ascii)}`, got === expected, `got ${JSON.stringify(got)}, want ${JSON.stringify(expected)}`);
}

function expectRoundTrip(label) {
  let enc, dec;
  try {
    enc = punycodeEncode(label);
    dec = punycodeDecode(enc);
  } catch (e) {
    check(`roundtrip ${JSON.stringify(label)}`, false, `threw ${e.message}`);
    return;
  }
  check(`roundtrip ${JSON.stringify(label)}`, dec === label, `encode=${JSON.stringify(enc)} decode=${JSON.stringify(dec)}`);
}

function expectThrow(ascii) {
  let threw = false;
  try {
    punycodeDecode(ascii);
  } catch (e) {
    threw = e instanceof Error;
  }
  check(`decode throws on ${JSON.stringify(ascii)}`, threw);
}

// --- 1. Known vectors ---
const vectors = [
  ['例', 'fsq'],
  ['москва', '80adxhks'],
  ['السعودية', 'mgberp4a5d4ar'],
  ['προγραμματισμός', 'mxaae0anacrikcslm7j'],
  ['straße', 'strae-oqa'],
  ['bücher', 'bcher-kva'],
  ['mañana', 'maana-pta'],
  ['☃', 'n3h'],
];
for (const [u, a] of vectors) {
  expectEncode(u, a);
  expectDecode(a, u);
  expectRoundTrip(u);
}

// Pure-ascii labels: encode is identity + trailing delimiter per RFC 3492,
// and Python's punycode codec behaves the same way ('abc' -> 'abc-').
expectEncode('abc', 'abc-');
expectDecode('abc-', 'abc');

// Case-insensitive digits on decode.
expectDecode('BCHER-KVA', 'bücher');
expectEncode('Bücher', 'Bcher-kva'); // uppercase basic chars copied as-is

// Astral characters (surrogate pairs).
expectRoundTrip('😀');
expectRoundTrip('a😀b');
expectRoundTrip('𠮷野家');
expectRoundTrip('𝄞music');

// Mixed / assorted round-trips.
for (const s of ['a例b', 'café', 'ドメイン', '한국', 'भारत', 'ไทย', 'ελληνικά', 'тест', 'abc', 'a-b-c', '例え', 'नमस्ते']) {
  expectRoundTrip(s);
}

// Malformed decode inputs must throw.
expectThrow('abc!def'); // '!' is not a valid digit after no-delimiter handling... actually '!' is not basic-copied; invalid digit
expectThrow('xn--'); // invalid digits ('x','n','-' ok, but '-'+... ) -- '-' mid-encoded part is an invalid digit
expectThrow('\u00e9'); // non-ASCII input
expectThrow('a'.repeat(100)); // overflow
expectThrow('-'); // nothing to decode, ends immediately -> actually decodes to ''; check below instead

// Decode of '-' alone is '' (delimiter, no basic chars, no encoded part) per RFC.
expectDecode('-', '');

// --- 2. Cross-check encode against reference executable ---
const EXE = '/workspace/dataset/test3_executable';
const exeLabels = [
  '例', '例え', '日本語', '中文', '한국어', '모스크바'.replace('모스크바', 'москва'),
  'москва', 'السعودية', 'مصر', 'προγραμματισμός', 'ελληνικά',
  'straße', 'bücher', 'mañana', 'café', 'a例b', '例a', 'a例',
  'ドメイン', 'भारत', 'नमस्ते', 'ไทย', 'тест', '파랑', '☃',
  'aaa', 'a-b', 'xn', 'παράδειγμα',
];
let exeChecked = 0;
let exeSkipped = 0;
for (const label of exeLabels) {
  let out;
  try {
    out = execFileSync(EXE, ['--domain', `${label}.com`, '--strict', 'True'], { encoding: 'utf8' });
  } catch (e) {
    console.error(`note: executable failed for ${JSON.stringify(label)}: ${e.message.split('\n')[0]}`);
    exeSkipped++;
    continue;
  }
  const m = out.match(/b'xn--([A-Za-z0-9-]+)\.com'/);
  if (!m) {
    if (/strict_encode_error/.test(out)) {
      exeSkipped++;
      continue;
    }
    check(`exe encode ${JSON.stringify(label)}`, false, `unexpected output: ${out.trim()}`);
    continue;
  }
  const expected = m[1];
  let got;
  try {
    got = punycodeEncode(label);
  } catch (e) {
    check(`exe encode ${JSON.stringify(label)}`, false, `threw ${e.message}`);
    continue;
  }
  check(`exe encode ${JSON.stringify(label)}`, got === expected, `got ${JSON.stringify(got)}, want ${JSON.stringify(expected)}`);
  exeChecked++;
}
console.log(`executable cross-checks: ${exeChecked} labels checked, ${exeSkipped} skipped (not valid IDNA)`);
check('at least 20 executable labels checked', exeChecked >= 20, `only ${exeChecked}`);

// --- 3. Cross-check decode against reference executable ---
const alabels = ['xn--fsq', 'xn--bcher-kva', 'xn--80adxhks', 'xn--strae-oqa', 'xn--n3h', 'xn--maana-pta'];
for (const alabel of alabels) {
  let out;
  try {
    out = execFileSync(EXE, ['--domain', `${alabel}.cn`, '--strict', 'True'], { encoding: 'utf8' });
  } catch (e) {
    check(`exe decode ${alabel}`, false, `executable failed: ${e.message.split('\n')[0]}`);
    continue;
  }
  // The ulabel line: find a bare non-ascii line in the output.
  const lines = out.split('\n').map((l) => l.trim()).filter(Boolean);
  const uline = lines.find((l) => /[^\x00-\x7f]/.test(l) && !l.startsWith("b'"));
  if (!uline) {
    check(`exe decode ${alabel}`, false, `no ulabel in output: ${out.trim()}`);
    continue;
  }
  const ascii = alabel.slice(4);
  let got;
  try {
    got = punycodeDecode(ascii);
  } catch (e) {
    check(`exe decode ${alabel}`, false, `threw ${e.message}`);
    continue;
  }
  check(`exe decode ${alabel}`, got === uline, `got ${JSON.stringify(got)}, want ${JSON.stringify(uline)}`);
}

console.log(`\n${passed} passed, ${failed} failed`);
if (failed > 0) {
  console.error('Failures:\n' + failures.join('\n'));
  process.exit(1);
}

